import type { GalleryMode } from '@types';
import { type RefObject, useCallback, useEffect, useState } from 'react';

interface CarouselScrollState {
  showPrev: boolean;
  showNext: boolean;
  scrollForward: () => void;
  scrollBackward: () => void;
}

export const useCarouselScroll = (
  containerRef: RefObject<HTMLDivElement | null>,
  layout: GalleryMode,
): CarouselScrollState => {
  const [showPrev, setShowPrev] = useState(false);
  const [showNext, setShowNext] = useState(false);

  const updateButtonVisibility = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollLeft, scrollWidth, clientWidth } = container;

    if (scrollWidth <= clientWidth) {
      setShowPrev(false);
      setShowNext(false);
      return;
    }

    setShowPrev(scrollLeft > 1);
    setShowNext(scrollLeft < scrollWidth - clientWidth - 1);
  }, [containerRef]);

  useEffect(() => {
    if (layout !== 'carousel') {
      setShowPrev(false);
      setShowNext(false);
      return;
    }

    const container = containerRef.current;
    if (!container) return;

    updateButtonVisibility();

    const resizeObserver = new ResizeObserver(updateButtonVisibility);
    resizeObserver.observe(container);

    container.addEventListener('scroll', updateButtonVisibility);

    return () => {
      container.removeEventListener('scroll', updateButtonVisibility);
      resizeObserver.disconnect();
    };
  }, [layout, containerRef, updateButtonVisibility]);

  const scrollForward = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    container.scrollBy({ left: container.clientWidth, behavior: 'smooth' });
  }, [containerRef]);

  const scrollBackward = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    container.scrollBy({ left: -container.clientWidth, behavior: 'smooth' });
  }, [containerRef]);

  return { showPrev, showNext, scrollForward, scrollBackward };
};

import { type RefObject, useCallback, useRef, useState } from 'react';

interface FullscreenViewerState {
  isViewerOpen: boolean;
  currentImageIndex: number;
  triggerRef: RefObject<HTMLElement | null>;
  openViewer: (index: number, element: HTMLElement) => void;
  closeViewer: () => void;
  handleNavigate: (index: number) => void;
}

export const useFullscreenViewer = (): FullscreenViewerState => {
  const [isViewerOpen, setIsViewerOpen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const triggerRef = useRef<HTMLElement | null>(null);

  const openViewer = useCallback((index: number, element: HTMLElement) => {
    triggerRef.current = element;
    setCurrentImageIndex(index);
    setIsViewerOpen(true);
  }, []);

  const closeViewer = useCallback(() => {
    setIsViewerOpen(false);
    setTimeout(() => {
      triggerRef.current?.focus();
      triggerRef.current = null;
    }, 300);
  }, []);

  const handleNavigate = useCallback((index: number) => {
    setCurrentImageIndex(index);
  }, []);

  return {
    isViewerOpen,
    currentImageIndex,
    triggerRef,
    openViewer,
    closeViewer,
    handleNavigate,
  };
};

