import type { GridFilterCondition, GridFilterState } from '@types';
import { useState } from 'react';

export type UseGridFilterParams = {
  filterState?: GridFilterState;
  onFilterChange?: (state: GridFilterState) => void;
};

export type UseGridFilterReturn = {
  filterState: GridFilterState;
  handleApplyFilter: (field: string, condition: GridFilterCondition) => void;
  handleClearFilter: (field: string) => void;
};

export const useGridFilter = ({
  filterState,
  onFilterChange,
}: UseGridFilterParams): UseGridFilterReturn => {
  const isControlled = filterState !== undefined;

  const [internalFilterState, setInternalFilterState] = useState<GridFilterState>({});

  const currentFilterState: GridFilterState = isControlled ? filterState : internalFilterState;

  const handleApplyFilter = (field: string, condition: GridFilterCondition) => {
    const next: GridFilterState = {
      ...currentFilterState,
      [field]: [...(currentFilterState[field] ?? []), condition],
    };

    if (!isControlled) {
      setInternalFilterState(next);
    }

    onFilterChange?.(next);
  };

  const handleClearFilter = (field: string) => {
    if (!currentFilterState[field]?.length) return;

    const next = { ...currentFilterState };
    delete next[field];

    if (!isControlled) {
      setInternalFilterState(next);
    }

    onFilterChange?.(next);
  };

  return {
    filterState: currentFilterState,
    handleApplyFilter,
    handleClearFilter,
  };
};

import type { GridItem } from '@types';
import { useState } from 'react';

export type UseGridSelectionParams = {
  data: GridItem[];
  onSelect?: (ids: string[]) => void;
};

export type UseGridSelectionReturn = {
  selectedIds: string[];
  isAllSelected: boolean;
  isAllCheckboxDisabled: boolean;
  handleSelectAll: () => void;
  handleDeselectAll: () => void;
  handleSelectRowById: (id: string) => void;
  handleDeselectRowById: (id: string) => void;
};

export const useGridSelection = ({
  data,
  onSelect,
}: UseGridSelectionParams): UseGridSelectionReturn => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const allIds = data.map((item) => item.id);
  const isAllSelected = allIds.length === selectedIds.length;
  const isAllCheckboxDisabled = data.some((item) => item?.disabled);

  const handleSelect = (ids: string[]) => {
    setSelectedIds(ids);
    onSelect?.(ids);
  };

  const handleSelectAll = () => {
    handleSelect(allIds);
  };

  const handleDeselectAll = () => {
    handleSelect([]);
  };

  const handleSelectRowById = (id: string) => {
    handleSelect([...selectedIds, id]);
  };

  const handleDeselectRowById = (id: string) => {
    handleSelect(selectedIds.filter((item) => item !== id));
  };

  return {
    selectedIds,
    isAllSelected,
    isAllCheckboxDisabled,
    handleSelectAll,
    handleDeselectAll,
    handleSelectRowById,
    handleDeselectRowById,
  };
};

import type { GridSortDirection } from '@enums';
import type { GridSortState } from '@types';
import { useState } from 'react';

import { getNextSortState } from '../Grid.helpers';

export type UseGridSortParams = {
  sortField?: string | null;
  sortDirection?: GridSortDirection | null;
  onSortChange?: (state: GridSortState) => void;
};

export type UseGridSortReturn = {
  sortState: GridSortState;
  handleSortClick: (field: string) => void;
};

export const useGridSort = ({
  sortField,
  sortDirection,
  onSortChange,
}: UseGridSortParams): UseGridSortReturn => {
  const isControlled = sortField !== undefined && sortDirection !== undefined;

  const [internalSortState, setInternalSortState] = useState<GridSortState>({
    field: null,
    direction: null,
  });

  const sortState: GridSortState = isControlled
    ? { field: sortField ?? null, direction: sortDirection ?? null }
    : internalSortState;

  const handleSortClick = (field: string) => {
    const nextState = getNextSortState(sortState, field);

    if (!isControlled) {
      setInternalSortState(nextState);
    }

    onSortChange?.(nextState);
  };

  return {
    sortState,
    handleSortClick,
  };
};

