    it('should have correct aria-label without title', () => {
      render(
        <table>
          <thead>
            <tr>
              <GridHeaderCell sortable={true} sortDirection={null} onSortClick={vi.fn()} />
            </tr>
          </thead>
        </table>,
      );

      expect(screen.getByRole('button', { name: 'Sort ascending' })).toBeInTheDocument();
