import { AlertMode, IconName } from '@enums';
import { describe, expect, it } from 'vitest';

import { getAlertIcon, getAlertTitle } from '../Alert.helpers';

describe('Alert.helpers', () => {
  describe('getAlertTitle', () => {
    it('returns the provided title if given', () => {
      expect(getAlertTitle(AlertMode.Info, 'Custom Title')).toBe('Custom Title');
    });

    it('returns default title based on mode', () => {
      expect(getAlertTitle(AlertMode.Info)).toBe('For your information');
      expect(getAlertTitle(AlertMode.Warning)).toBe('Please pay attention');
      expect(getAlertTitle(AlertMode.Error)).toBe('Something went wrong');
      expect(getAlertTitle(AlertMode.Success)).toBe('Everything is okay');
      expect(getAlertTitle(AlertMode.Help)).toBe('Useful tip');
    });

    it('returns generic title for unknown mode', () => {
      expect(getAlertTitle('unknown' as AlertMode)).toBe('Alert');
    });
  });

  describe('getAlertIcon', () => {
    it('returns the provided icon if given', () => {
      expect(getAlertIcon(AlertMode.Info, IconName.Save)).toBe(IconName.Save);
    });

    it('returns default icon based on mode', () => {
      expect(getAlertIcon(AlertMode.Info)).toBe(IconName.Info);
      expect(getAlertIcon(AlertMode.Warning)).toBe(IconName.AlertTriangle);
      expect(getAlertIcon(AlertMode.Error)).toBe(IconName.XOctagon);
      expect(getAlertIcon(AlertMode.Success)).toBe(IconName.CheckCircle);
      expect(getAlertIcon(AlertMode.Help)).toBe(IconName.LifeBuoy);
    });

    it('returns undefined for unknown mode', () => {
      expect(getAlertIcon('unknown' as AlertMode)).toBeUndefined();
    });
  });
});

src/hooks/use-key-press/__tests__/use-ke.source:
import { render } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useRef } from 'react';
import { describe, expect, it, vi } from 'vitest';

import { useKeyPress } from '../use-key-press';

const TestComponent = ({ keyCode, onKeyPress }: { keyCode: string; onKeyPress: () => void }) => {
  const ref = useRef<HTMLDivElement>(null);
  useKeyPress({ ref, keyCode, onKeyPress });

  return (
    <div ref={ref} data-testid="test-element">
      Test Text
    </div>
  );
};

describe('useKeyPress  tests:', () => {
  it('should call onKeyPress handler when the specific key is pressed', async () => {
    const onKeyPress = vi.fn();
    const keyCode = 'Escape';

    const { getByTestId } = render(<TestComponent keyCode={keyCode} onKeyPress={onKeyPress} />);

    const testElement = getByTestId('test-element');

    // Focus the test element to ensure ref is current
    testElement.focus();

    // Simulate pressing the specific key
    await userEvent.keyboard(`{${keyCode}}`);

    expect(onKeyPress).toHaveBeenCalled();
  });

  it('should not call onKeyPress handler when a different key is pressed', async () => {
    const onKeyPress = vi.fn();
    const keyCode = 'Escape';

    const { getByTestId } = render(<TestComponent keyCode={keyCode} onKeyPress={onKeyPress} />);

    const testElement = getByTestId('test-element');

    // Focus the test element to ensure ref is current
    testElement.focus();

    // Simulate pressing a different key
    await userEvent.keyboard('[Enter]');

    expect(onKeyPress).not.toHaveBeenCalled();
  });
});

src/hooks/use-element-ids/__tests__/use-.source:
import { renderHook } from '@testing-library/react';
import { useId } from 'react';
import { beforeEach, describe, expect, it, type Mock, vi } from 'vitest';

import { useElementIds } from '../use-element-ids';

// Mock the useId hook
vi.mock('react', async () => {
  const actual = await vi.importActual('react');
  return {
    ...actual,
    useId: vi.fn(),
  };
});

describe('useElementIds', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('should return elementId, errorId, and dropdownId based on provided id', () => {
    const customId = 'custom-element-id';
    const { result } = renderHook(() => useElementIds(customId));

    expect(result.current.elementId).toBe(customId);
    expect(result.current.errorId).toBe(`${customId}_error`);
    expect(result.current.dropdownId).toBe(`${customId}_dropdown`);
  });

  it('should return elementId, errorId, and dropdownId based on generated id if no id is provided', () => {
    const mockGeneratedId = 'random-generated-id';
    (useId as Mock).mockReturnValue(mockGeneratedId);

    const { result } = renderHook(() => useElementIds());

    expect(result.current.elementId).toBe(mockGeneratedId);
    expect(result.current.errorId).toBe(`${mockGeneratedId}_error`);
    expect(result.current.dropdownId).toBe(`${mockGeneratedId}_dropdown`);
  });

  it('should call useId when no id is provided', () => {
    const mockGeneratedId = 'random-generated-id';
    (useId as Mock).mockReturnValue(mockGeneratedId);

    renderHook(() => useElementIds());

    expect(useId).toHaveBeenCalled();
  });
});

src/hooks/use-form-pending/__tests__/use.source:
import { FormContext } from '@components/contexts';
import { renderHook } from '@testing-library/react';
import type { FC, PropsWithChildren } from 'react';
import { describe, expect, it } from 'vitest';

import { useFormPending } from '../use-form-pending';

describe('useFormPending', () => {
  it('should return false when no FormContext provider exists', () => {
    const { result } = renderHook(() => useFormPending());
    expect(result.current).toBe(false);
  });

  it('should return true when FormContext provides isPending as true', () => {
    const wrapper: FC<PropsWithChildren> = ({ children }) => (
      <FormContext.Provider value={{ isPending: true }}>{children}</FormContext.Provider>
    );

    const { result } = renderHook(() => useFormPending(), { wrapper });
    expect(result.current).toBe(true);
  });

  it('should return false when FormContext provides isPending as false', () => {
    const wrapper: FC<PropsWithChildren> = ({ children }) => (
      <FormContext.Provider value={{ isPending: false }}>{children}</FormContext.Provider>
    );

    const { result } = renderHook(() => useFormPending(), { wrapper });
    expect(result.current).toBe(false);
  });
});

